use serde::{Deserialize, Serialize};
use wasm_bindgen::{closure::Closure, JsCast};
use web_sys::{HtmlInputElement, HtmlSelectElement, HtmlTextAreaElement, Position};
use yew::prelude::*;

const STORAGE_KEY: &str = "signal-sleuth-reports-v1";
const STUDIO: (f64, f64) = (30.0972, -95.6161);
const KRLY: (f64, f64) = (30.1017, -95.6218);

#[derive(Clone, PartialEq, Serialize, Deserialize)]
struct Report { frequency: String, station: String, latitude: f64, longitude: f64, strength: u8, quality: String, features: String, notes: String, timestamp: String }

fn distance_miles(a: (f64,f64), b: (f64,f64)) -> f64 { let r=3958.8; let (p1,p2)=(a.0.to_radians(),b.0.to_radians()); let dp=(b.0-a.0).to_radians(); let dl=(b.1-a.1).to_radians(); let h=(dp/2.0).sin().powi(2)+p1.cos()*p2.cos()*(dl/2.0).sin().powi(2); r*2.0*h.sqrt().atan2((1.0-h).sqrt()) }
fn bearing(a:(f64,f64),b:(f64,f64))->f64 { let p1=a.0.to_radians(); let p2=b.0.to_radians(); let dl=(b.1-a.1).to_radians(); let y=dl.sin()*p2.cos(); let x=p1.cos()*p2.sin()-p1.sin()*p2.cos()*dl.cos(); (y.atan2(x).to_degrees()+360.0)%360.0 }
fn compass(d:f64)->&'static str { const P:[&str;8]=["N","NE","E","SE","S","SW","W","NW"]; P[((d/45.0).round() as usize)%8] }
fn load_reports()->Vec<Report>{ web_sys::window().and_then(|w|w.local_storage().ok().flatten()).and_then(|s|s.get_item(STORAGE_KEY).ok().flatten()).and_then(|v|serde_json::from_str(&v).ok()).unwrap_or_default() }
fn save_reports(r:&[Report]) { if let (Some(s),Ok(v))=(web_sys::window().and_then(|w|w.local_storage().ok().flatten()),serde_json::to_string(r)){let _=s.set_item(STORAGE_KEY,&v);} }

#[function_component(App)]
fn app()->Html{
 let frequency=use_state(||"99.9 FM".into()); let station=use_state(||"Mystery Signal".into()); let latitude=use_state(||STUDIO.0.to_string()); let longitude=use_state(||STUDIO.1.to_string()); let strength=use_state(||65u8); let quality=use_state(||"Clear".into()); let features=use_state(String::new); let notes=use_state(String::new); let status=use_state(||"Ready for a field observation".into()); let reports=use_state(load_reports);
 let lat=latitude.parse::<f64>().unwrap_or(STUDIO.0); let lon=longitude.parse::<f64>().unwrap_or(STUDIO.1); let here=(lat,lon); let ds=distance_miles(STUDIO,here); let dk=distance_miles(KRLY,here); let br=bearing(STUDIO,here);
 let locate={let latitude=latitude.clone();let longitude=longitude.clone();let status=status.clone();Callback::from(move |_|{status.set("Requesting iPhone location…".into());if let Some(nav)=web_sys::window().map(|w|w.navigator()){if let Ok(geo)=nav.geolocation(){let la=latitude.clone();let lo=longitude.clone();let st=status.clone();let ok=Closure::<dyn FnMut(Position)>::new(move |p:Position|{la.set(format!("{:.6}",p.coords().latitude()));lo.set(format!("{:.6}",p.coords().longitude()));st.set("Location locked — ready to record".into());});let _=geo.get_current_position(ok.as_ref().unchecked_ref());ok.forget();}else{status.set("Location unavailable — enter coordinates manually".into());}}})};
 let record={let frequency=frequency.clone();let station=station.clone();let strength=strength.clone();let quality=quality.clone();let features=features.clone();let notes=notes.clone();let reports=reports.clone();let status=status.clone();Callback::from(move |_|{let mut all=(*reports).clone();let timestamp=js_sys::Date::new_0().to_locale_string("en-US",&wasm_bindgen::JsValue::UNDEFINED).as_string().unwrap_or_default();all.insert(0,Report{frequency:(*frequency).clone(),station:(*station).clone(),latitude:lat,longitude:lon,strength:*strength,quality:(*quality).clone(),features:(*features).clone(),notes:(*notes).clone(),timestamp});save_reports(&all);reports.set(all);status.set("Observation secured in this iPhone".into());notes.set(String::new());})};
 let clear={let reports=reports.clone();let status=status.clone();Callback::from(move |_|{save_reports(&[]);reports.set(vec![]);status.set("Field log cleared".into());})};
 let report_cards: Html = reports.iter().take(8).map(|r| html! {
   <div class="report">
     <div class="report-head">
       <strong>{format!("{} • {}", r.frequency, r.station)}</strong>
       <small>{format!("{}%", r.strength)}</small>
     </div>
     <p>{format!("{} • {:.5}, {:.5}", r.quality, r.latitude, r.longitude)}</p>
     {if r.notes.is_empty() { Html::default() } else { html! { <p>{&r.notes}</p> } }}
     <small>{&r.timestamp}</small>
   </div>
 }).collect();
 html!{<main class="app"><header class="topbar"><div><p class="eyebrow">MIKEGYVER STUDIO FIELD SYSTEM</p><h1>{"Signal Sleuth"}</h1><p class="subtitle">{"Tomball-area radio intelligence console"}</p></div><span class="wasm">{"RUST • WASM"}</span></header><div class="status"><i class="pulse"></i>{&*status}</div><section class="grid"><article class="panel form"><h2>{"New observation"}</h2><p class="hint">{"Log what your radio and your eyes detect."}</p><div class="form-grid"><label>{"Frequency"}<input value={(*frequency).clone()} oninput={{let s=frequency.clone();Callback::from(move|e:InputEvent|s.set(e.target_unchecked_into::<HtmlInputElement>().value()))}} /></label><label>{"Station / label"}<input value={(*station).clone()} oninput={{let s=station.clone();Callback::from(move|e:InputEvent|s.set(e.target_unchecked_into::<HtmlInputElement>().value()))}} /></label><label>{"Latitude"}<input inputmode="decimal" value={(*latitude).clone()} oninput={{let s=latitude.clone();Callback::from(move|e:InputEvent|s.set(e.target_unchecked_into::<HtmlInputElement>().value()))}} /></label><label>{"Longitude"}<input inputmode="decimal" value={(*longitude).clone()} oninput={{let s=longitude.clone();Callback::from(move|e:InputEvent|s.set(e.target_unchecked_into::<HtmlInputElement>().value()))}} /></label><label class="span-2">{"Signal strength"}<div class="range-row"><input type="range" min="0" max="100" value={strength.to_string()} oninput={{let s=strength.clone();Callback::from(move|e:InputEvent|s.set(e.target_unchecked_into::<HtmlInputElement>().value().parse().unwrap_or(0)))}}/><span class="meter-value">{format!("{}%",*strength)}</span></div></label><label>{"Audio quality"}<select onchange={{let s=quality.clone();Callback::from(move|e:Event|s.set(e.target_unchecked_into::<HtmlSelectElement>().value()))}}><option>{"Clear"}</option><option>{"Noisy"}</option><option>{"Fading"}</option><option>{"Interference"}</option></select></label><label>{"Tower features"}<input placeholder="Dishes, panels, lights…" value={(*features).clone()} oninput={{let s=features.clone();Callback::from(move|e:InputEvent|s.set(e.target_unchecked_into::<HtmlInputElement>().value()))}} /></label><label class="span-2">{"Field notes"}<textarea placeholder="What did you hear or observe?" value={(*notes).clone()} oninput={{let s=notes.clone();Callback::from(move|e:InputEvent|s.set(e.target_unchecked_into::<HtmlTextAreaElement>().value()))}} /></label></div><div class="actions"><button onclick={locate}>{"⌖ Use My Location"}</button><button onclick={clear}>{"Clear Log"}</button><button class="primary" onclick={record}>{"Record Observation"}</button></div></article><article class="panel"><h2>{"Live analysis"}</h2><p class="hint">{"Calculated locally by Rust."}</p><div class="analysis"><div class="metric"><span>{"From studio"}</span><strong>{format!("{:.2} mi",ds)}</strong></div><div class="metric"><span>{"From KRLY"}</span><strong>{format!("{:.2} mi",dk)}</strong></div><div class="metric"><span>{"Bearing"}</span><strong>{format!("{:.0}° {}",br,compass(br))}</strong></div><div class="metric"><span>{"Signal"}</span><strong>{format!("{} / 100",*strength)}</strong></div><div class="metric wide"><span>{"Assessment"}</span><strong>{if *strength>79{"Strong local candidate"}else if *strength>49{"Usable investigation lead"}else{"Weak or distant signal"}}</strong></div></div></article><article class="panel skynet"><h2>{"SKYNET Analysis Mode"}</h2><div class="terminal">{format!("> OBSERVATIONS: {:02}\n> NODE BEARING: {:.0}° {}\n> SIGNAL CONFIDENCE: {}%\n> HUMAN OBSERVER: DETECTED",reports.len(),br,compass(br),*strength)}</div></article><article class="panel"><h2>{"Field log"}</h2><p class="hint">{format!("{} observations stored on this device",reports.len())}</p><div class="reports">{if reports.is_empty(){html!{<div class="empty">{"No signals captured yet."}</div>}}else{report_cards}}</div></article></section></main>}
}

fn main(){yew::Renderer::<App>::new().render();}
